method largest_divisor(n: int) returns (result: int)
    requires n > 1
    ensures result > 0 && result < n && n % result == 0
{
    var i := n - 1;
    while i > 0
        invariant i > 0
        invariant i < n
        invariant n % i != 0 || (result == i && result > 0 && result < n)
    {
        if n % i == 0 {
            result := i;
            return;
        }
        i := i - 1;
    }

    // This part should never be reached because of the precondition n > 1
    result := 1; // In case of any unexpected behavior, we return 1 (the smallest divisor)
}
```

